/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.makeInputFromParent();
        for (let i = 1; i < 13; i++) {
            $("#isu_dd" + i).datepicker(myDateOpts);
            $("#redmpt_dd" + i).datepicker(myDateOpts);
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf10001.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_datefmt_isu_dd();
        scwin.init_datefmt_redmpt_dd();
        scwin.init_datefmt_isu_dd_r1();
        scwin.init_datefmt_redmpt_dd_r1();
        scwin.init_datefmt_isu_dd_r2();
        scwin.init_datefmt_redmpt_dd_r2();
        scwin.init_datefmt_isu_dd_r3();
        scwin.init_datefmt_redmpt_dd_r3();
        scwin.init_datefmt_isu_dd_r4();
        scwin.init_datefmt_redmpt_dd_r4();
        scwin.init_datefmt_isu_dd_r5();
        scwin.init_datefmt_redmpt_dd_r5();
        scwin.init_datefmt_isu_dd_r6();
        scwin.init_datefmt_redmpt_dd_r6();
        scwin.init_datefmt_isu_dd_r7();
        scwin.init_datefmt_redmpt_dd_r7();
        scwin.init_datefmt_isu_dd_r8();
        scwin.init_datefmt_redmpt_dd_r8();
        scwin.init_datefmt_isu_dd_r9();
        scwin.init_datefmt_redmpt_dd_r9();
        scwin.init_datefmt_isu_dd_r10();
        scwin.init_datefmt_redmpt_dd_r10();
        scwin.init_datefmt_isu_dd_r11();
        scwin.init_datefmt_redmpt_dd_r11();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf10001.onpageload' });
    }
};


