 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_isuYyyy_onblur = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_isuYyyy_onblur — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnCheckCurrentTime($c.util.getComponent("ipt_isuYyyy"));
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf10001.ipt_isuYyyy_onblur' }); }
};

